export const productCardTemplate = "<a class=\"pcard\" href=\"/<%= lang %>/product/<%= p.slug %>\">\n  <div class=\"pcard-media\" data-cat=\"<%= p.cat_slug || '' %>\">\n    <%- thumb(p, lang) %>\n  </div>\n  <div class=\"pcard-body\">\n    <% if (p.latin_name) { %><span class=\"pcard-latin\"><%= p.latin_name %></span><% } %>\n    <h3 class=\"pcard-name\"><%= lang === 'zh' ? p.name_zh : p.name_en %></h3>\n    <p class=\"pcard-sub\"><%= lang === 'zh' ? p.name_en : p.name_zh %></p>\n    <dl class=\"pcard-meta\">\n      <div><dt><%= t('prod.origin') %></dt><dd><%= lang === 'zh' ? p.origin_zh : p.origin_en %></dd></div>\n      <div><dt><%= t('prod.part') %></dt><dd><%= lang === 'zh' ? p.part_zh : p.part_en %></dd></div>\n    </dl>\n    <div class=\"pcard-foot\">\n      <span class=\"pcard-price\"><%= fmtPrice(p) %></span>\n      <span class=\"pcard-more\"><%= t('prod.detail') %> →</span>\n    </div>\n  </div>\n</a>\n";
